import React, { useMemo, useState } from 'react';
import { APP_VERSION_LABEL } from '../config/version';
import { useNavigate } from 'react-router-dom';
import { usePermissions, usePlatform } from '../hooks/usePermissions';
import { getHomeFeatures } from '../config/homeFeatures';

const TelegramHome: React.FC = () => {
  const navigate = useNavigate();
  const navigateTo = (path: string) => {
    try {
      navigate(path);
    } catch {}
  };
  const { isWeb, isMiniApp } = usePlatform();

  const { state } = usePermissions();

  // Прогресс авторизации: 0=tg_id? 1=OTP issue, 2=issued
  const [authStep, setAuthStep] = useState<number>(0);
  const [authError, setAuthError] = useState<string | null>(null);
  const stepItems = useMemo(() => ([
    { title: 'MiniApp', description: 'tg_id найден' },
    { title: 'OTP', description: 'выдача кода' },
    { title: 'Готово', description: 'код выдан' },
  ]), []);
  // Без tg_id роли могут быть пустыми — не блокируем UI
  const isArchitect = state.roles?.some(r => r.name === 'architect');
  const isAdmin = state.roles?.some(r => r.name === 'admin');

  const features = getHomeFeatures(!!isAdmin, !!isArchitect);

  const requestWebAccess = async () => {
    try {
      const telegramUser = (window as any).Telegram?.WebApp?.initDataUnsafe?.user;
      const tgId = telegramUser?.id;
      
      if (!telegramUser || !tgId) {
        setAuthError('400: отсутствует tg_id (MiniApp контекст)');
        return;
      }

      console.log('[WEB_ACCESS] 🚀 Создаем веб доступ для пользователя:', telegramUser);
      
      const headers: Record<string, string> = {};
      if (tgId) headers['X-Telegram-User-ID'] = String(tgId);
      setAuthError(null);
      setAuthStep(0);
      setAuthStep(1);

      // Попытка №1: безопасная сессия через HttpOnly cookie (на том же домене)
      // Сервер должен установить Set-Cookie: Secure; SameSite=Lax/Strict; HttpOnly; короткий TTL
      try {
        const respCookie = await fetch('/api/web-auth/issue-web-cookie', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...headers },
          credentials: 'include',
        });
        if (respCookie.ok) {
          setAuthStep(2);
          // Даже при успешной cookie — выдаём короткий OTP и предлагаем кнопку открытия WebAuth,
          // т.к. cookie из WebApp могут не шариться с внешним браузером.
          let otp: string | null = null;
          try {
            const r = await fetch('/api/web-auth/issue-one-time-token', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', ...headers },
              credentials: 'include',
            });
            if (r.ok) {
              const j = await r.json();
              otp = j?.otp || null;
            }
          } catch {}

          const origin = (window.location && window.location.origin) || 'https://mini.soulpulse.art';
          const userDataForUrl = {
            id: telegramUser.id,
            first_name: telegramUser.first_name,
            last_name: telegramUser.last_name,
            username: telegramUser.username,
            language_code: telegramUser.language_code,
            photo_url: telegramUser.photo_url
          };
          const userDataEncoded = encodeURIComponent(JSON.stringify(userDataForUrl));
          const url = otp
            ? `${origin}/webauth?tg_id=${encodeURIComponent(String(tgId))}&otp=${encodeURIComponent(otp)}&user_data=${userDataEncoded}`
            : `${origin}/webauth?tg_id=${encodeURIComponent(String(tgId))}&user_data=${userDataEncoded}`;

          // Модальное окно с кнопкой открытия WebAuth
          const container = document.createElement('div');
          container.style.lineHeight = '1.6';
          container.style.fontSize = '14px';

          const title = document.createElement('div');
          title.innerHTML = '✅ Сессия выдана';
          title.style.fontSize = '16px';
          title.style.fontWeight = 'bold';
          title.style.marginBottom = '16px';
          title.style.color = 'var(--sp-color-success)';

          const info = document.createElement('div');
          info.style.marginBottom = '16px';
          info.innerHTML = `
            <div style="margin-bottom: 8px;">Нажмите кнопку ниже, чтобы открыть WebAuth.</div>
            ${otp ? `<div style="margin-bottom: 8px;"><strong>OTP:</strong> <code style="background: #f1f5f9; padding: 2px 6px; border-radius: 4px; font-family: monospace;">${otp}</code></div>` : ''}
          `;

          const linkSection = document.createElement('div');
          linkSection.innerHTML = `
            <button id="sp_open_webauth_btn_cookie" style="
              display: inline-block;
              background: #3B82F6;
              color: white;
              text-decoration: none;
              padding: 8px 16px;
              border-radius: 6px;
              font-size: 13px;
              margin-bottom: 8px;
              cursor: pointer;
            ">🔗 Открыть WebAuth</button>
            <div style="font-size: 12px; color: var(--sp-text-secondary); word-break: break-all;">${url}</div>
          `;

          container.appendChild(title);
          container.appendChild(info);
          container.appendChild(linkSection);
          const wrap = document.createElement('div');
          wrap.style.position = 'fixed';
          wrap.style.inset = '0';
          wrap.style.background = 'rgba(0,0,0,0.5)';
          wrap.style.display = 'flex';
          wrap.style.alignItems = 'center';
          wrap.style.justifyContent = 'center';
          const modal = document.createElement('div');
          modal.style.background = '#fff';
          modal.style.padding = '16px';
          modal.style.borderRadius = '8px';
          modal.style.maxWidth = '480px';
          modal.style.fontSize = '14px';
          modal.appendChild(container);
          const ok = document.createElement('button');
          ok.textContent = 'OK';
          ok.style.marginTop = '12px';
          ok.onclick = () => document.body.removeChild(wrap);
          modal.appendChild(ok);
          wrap.appendChild(modal);
          document.body.appendChild(wrap);

          try {
            const btn = document.getElementById('sp_open_webauth_btn_cookie');
            if (btn) {
              btn.addEventListener('click', () => {
                try {
                  // Внешние открытия запрещены для внутренних маршрутов — используем навигацию
                  open(url);
                } catch { open(url); }
              });
            }
          } catch {}

          return;
        }
      } catch (e) {
        // падаем на OTP фоллбек
      }

      // Фоллбек: OTP по старой схеме (с коротким TTL) — только если cookie не выданы
      let respOtp = await fetch('/api/web-auth/issue-one-time-token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...headers },
        credentials: 'include',
      });
      if (!respOtp.ok && respOtp.status === 404) {
        try {
          respOtp = await fetch('/api/miniapp/auth/issue-one-time-token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...headers },
            credentials: 'include',
          });
        } catch {}
      }
      if (!respOtp.ok) {
        const t = await respOtp.text().catch(()=> '');
        const code = respOtp.status;
        const msg = code === 401 ? '401: нет cookie/Bearer' : code === 404 ? '404: маршрут не найден' : (code >= 500 ? `5xx: сервер/сеть (${code})` : `HTTP ${code}`);
        setAuthError(`${msg}${t ? ' - ' + t : ''}`);
        return;
      }

      const data = await respOtp.json();
      const otp = data.otp;
      const issuedTgId = data.tg_id || tgId;
      setAuthStep(2);

      // Готовим данные пользователя для передачи в URL (минимум, без лишних PII)
      const userDataForUrl = {
        id: telegramUser.id,
        first_name: telegramUser.first_name,
        last_name: telegramUser.last_name,
        username: telegramUser.username,
        language_code: telegramUser.language_code,
        photo_url: telegramUser.photo_url
      };
      
      const origin = (window.location && window.location.origin) || 'https://mini.soulpulse.art';
      
      // Создаем URL с данными пользователя И OTP токеном (двойная защита)
      const userDataEncoded = encodeURIComponent(JSON.stringify(userDataForUrl));
      const url = `${origin}/webauth?tg_id=${encodeURIComponent(issuedTgId)}&otp=${encodeURIComponent(otp)}&user_data=${userDataEncoded}`;

      console.log('[WEB_ACCESS] 🔗 Создана ссылка:', url);

      // Показать код и ссылку (OTP)
      const container = document.createElement('div');
      container.style.lineHeight = '1.6';
      container.style.fontSize = '14px';
      
      const title = document.createElement('div');
      title.innerHTML = '✅ Веб-доступ выдан на 5 минут';
      title.style.fontSize = '16px';
      title.style.fontWeight = 'bold';
      title.style.marginBottom = '16px';
      title.style.color = 'var(--sp-color-success)';
      
      const info = document.createElement('div');
      info.style.marginBottom = '16px';
      info.innerHTML = `
        <div style="margin-bottom: 8px;"><strong>OTP:</strong> <code style="background: #f1f5f9; padding: 2px 6px; border-radius: 4px; font-family: monospace;">${otp}</code></div>
        <div style="margin-bottom: 8px;"><strong>Telegram ID:</strong> ${issuedTgId}</div>
        <div><strong>Пользователь:</strong> ${telegramUser.first_name} ${telegramUser.last_name || ''}</div>
      `;
      
      const linkSection = document.createElement('div');
      linkSection.innerHTML = `
        <div style="margin-bottom: 8px; font-weight: bold;">Откройте WebAuth для входа:</div>
        <button id="sp_open_webauth_btn" style="
          display: inline-block;
          background: #3B82F6;
          color: white;
          text-decoration: none;
          padding: 8px 16px;
          border-radius: 6px;
          font-size: 13px;
          margin-bottom: 8px;
          cursor: pointer;
        ">🔗 Открыть WebAuth</button>
        <div style="font-size: 12px; color: var(--sp-text-secondary); word-break: break-all;">${url}</div>
      `;
      
      container.appendChild(title);
      container.appendChild(info);
      container.appendChild(linkSection);
      const wrap = document.createElement('div');
      wrap.style.position = 'fixed';
      wrap.style.inset = '0';
      wrap.style.background = 'rgba(0,0,0,0.5)';
      wrap.style.display = 'flex';
      wrap.style.alignItems = 'center';
      wrap.style.justifyContent = 'center';
      const modal = document.createElement('div');
      modal.style.background = '#fff';
      modal.style.padding = '16px';
      modal.style.borderRadius = '8px';
      modal.style.maxWidth = '480px';
      modal.style.fontSize = '14px';
      modal.appendChild(container);
      const ok = document.createElement('button');
      ok.textContent = 'OK';
      ok.style.marginTop = '12px';
      ok.onclick = () => document.body.removeChild(wrap);
      modal.appendChild(ok);
      wrap.appendChild(modal);
      document.body.appendChild(wrap);

      try {
        const btn = document.getElementById('sp_open_webauth_btn');
        if (btn) {
          btn.addEventListener('click', () => {
            try { open(url); } catch { open(url); }
          });
        }
      } catch {}
    } catch (e) {
      console.error(e);
      setAuthError('5xx: сбой при выдаче OTP');
    }
  };

  return (
    <div className="telegram-home sp-edge-highlight" style={{
      background: 'var(--sp-gradient-background)',
      minHeight: '100%',
      color: 'var(--sp-text-primary)',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
      overflowY: 'auto',
      WebkitOverflowScrolling: 'touch',
      overflowX: 'hidden'
    }}>
      {/* Заголовок перенесён в ModernHeader, нижняя полоска убрана для экономии места */}

      {/* Main Content */}
      <div className="sp-card-elevated sp-edge-highlight" style={{ padding: '14px 16px', margin: '12px 12px 10px', boxSizing: 'border-box', width: '100%', maxWidth: '100%', overflowX: 'hidden' }}>
        {/* Индикатор шага авторизации */}
        <div style={{ marginBottom: 12 }}>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
            {stepItems.map((s, idx) => (
              <div key={s.title} style={{ display: 'flex', alignItems: 'center', opacity: idx <= authStep ? 1 : 0.4, fontSize: 12, color: 'var(--sp-text-secondary)' }}>
                <div style={{
                  width: 18, height: 18, borderRadius: 9,
                  background: idx <= authStep ? 'var(--sp-color-primary)' : 'rgba(0,0,0,0.12)',
                  color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  marginRight: 6
                }}>{idx+1}</div>
                <div><strong>{s.title}</strong><span style={{ marginLeft: 6 }}>{s.description}</span></div>
                {idx < stepItems.length - 1 && <div style={{ width: 14, height: 1, background: 'rgba(0,0,0,0.15)', margin: '0 8px' }} />}
              </div>
            ))}
          </div>
          {!!authError && (
            <div style={{ marginTop: 8, background: '#ffebee', color: '#b71c1c', border: '1px solid #ffcdd2', padding: '8px 10px', borderRadius: 6, fontSize: 12 }}>
              {authError}
            </div>
          )}
        </div>
        {/* Quick Actions */}
        <div style={{ marginBottom: '24px' }}>
          <h2 style={{
            fontSize: '16px',
            fontWeight: '500',
            color: 'var(--sp-text-primary)',
            margin: '0 0 16px 0'
          }}>
            Быстрые действия
          </h2>
          
          <div style={{ display: 'grid', gap: '10px', gridTemplateColumns: '1fr', width: '100%', boxSizing: 'border-box' }}>
            {features.map((feature) => (
              <div
                key={feature.id}
                onClick={() => navigateTo(feature.route)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') navigateTo(feature.route); }}
                className="telegram-home-feature-card sp-edge-highlight"
                style={{ display: 'flex', alignItems: 'center', gap: '12px', width: '100%', boxSizing: 'border-box' }}
              >
                <div style={{
                  fontSize: '24px',
                  minWidth: '32px',
                  textAlign: 'center'
                }}>
                  {feature.icon.startsWith('/') ? (
                    <img 
                      src={feature.icon} 
                      alt={feature.title}
                      style={{ 
                        width: '24px', 
                        height: '24px',
                        objectFit: 'contain',
                        borderRadius: '6px',
                        boxShadow: '0 1px 2px rgba(0,0,0,0.12)'
                      }} 
                    />
                  ) : (
                    feature.icon
                  )}
                </div>
                <div style={{ flex: 1 }}>
                  <h3 style={{
                    margin: 0,
                    fontSize: '16px',
                    fontWeight: '500',
                    color: 'var(--sp-text-primary)',
                    marginBottom: '2px'
                  }}>
                    {feature.title}
                  </h3>
                  <p style={{
                    margin: 0,
                    fontSize: '14px',
                    color: 'var(--sp-text-secondary)',
                    lineHeight: '1.3'
                  }}>
                    {feature.description}
                  </p>
                </div>
                <div style={{
                  fontSize: '18px',
                  color: 'var(--sp-text-secondary)'
                }}>
                  →
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Info Section removed per request */}

        {/* Recommendations: только кнопка веб‑доступа */}
        <div className="telegram-home-recommendation-card">
          <button
            onClick={requestWebAccess}
            className="telegram-home-button success"
          >
            🔓 Открыть web‑доступ (5 мин)
          </button>
        </div>
      </div>
    </div>
  );
};

export default TelegramHome;
