export function getHomeFeatures(isAdmin: boolean, isArchitect: boolean): HomeFeature[] {
  const base = getBaseFeatures();
  const extra: HomeFeature[] = [];
  if (isArchitect) {
    extra.push(...getArchitectFeatures());
  }
  if (isAdmin && !extra.some(f => f.id === 'soul-logs')) {
    extra.push(...getAdminFeatures());
  }
  // Дедупликация по id
  const uniq = new Map<string, HomeFeature>();
  [...base, ...extra].forEach(f => { if (!uniq.has(f.id)) uniq.set(f.id, f); });
  return Array.from(uniq.values());
}


